      // current segment (its closedAt, or firstRecordAt fallback).
      state.current().noteRecordAt(timestamp);
      if (type == 'custom') {
        _handleSummary(decoded, state);
        continue;
      }
      if (type != 'message') continue;
      _handleAssistantMessage(decoded, state);
    }
