            for line in text.splitlines():
                if not line.strip():
                    continue
                rid = None
                try:
                    record = json.loads(line)
                    if isinstance(record, dict):
                        rid = record.get("id")
                except json.JSONDecodeError:
                    pass
                if rid is not None:
                    if rid in seen_ids:
