def _dedup_session_text(session_dirs):
    """Concatenated session lines, deduped by record id (E6).

    A replay/takeover trial ships two session files whose overlapping
    turns re-record the same assistant records under the same ids; usage
    must be counted once per record, not once per file.
    """
    seen_ids = set()
    lines = []
    for sessions in session_dirs:
        for path in sorted(sessions.glob("*.jsonl")):
            try:
                text = path.read_text(errors="replace")
            except OSError as exc:
                print(
                    f"[post-mortem] warning: unreadable session file "
                    f"{path}: {exc}",
                    file=sys.stderr,
                )
                continue
            for line in text.splitlines():
                if not line.strip():
                    continue
                rid = None
                try:
                    record = json.loads(line)
                    if isinstance(record, dict):
                        rid = record.get("id")
                except json.JSONDecodeError:
                    pass
                if rid is not None:
                    if rid in seen_ids:
                        continue
                    seen_ids.add(rid)
                lines.append(line)
    return "\n".join(lines)


def _fold_row(row, session_dirs):
    """(input, output, warning, usage_incomplete) for one row from its
    session files.

    (None, None, warning, usage_incomplete) means the session files exist
    but say nothing usable — tokens: null, the E4 degradation — with
    `usage_incomplete` set when a request-side record dangled (gh-1643:
