      messageCount: json['messageCount'] as int? ?? 0,
      systemPromptChars: json['systemPromptChars'] as int? ?? 0,
      toolCount: json['toolCount'] as int? ?? 0,
      toolNames: [
        for (final name in (json['toolNames'] as List?) ?? const [])
